import { createClient } from 'redis';

const client = createClient();

export async function getCachedUser(id: string, fallbackDbFetch: () => Promise<any>) {
  const key = `user:${id}:profile`;
  try {
    const cached = await client.get(key);
    if (cached) return JSON.parse(cached);
  } catch (err) {
    console.error('Redis read failed, falling back to DB', err);
  }

  const data = await fallbackDbFetch();

  try {
    // Add 10% jitter to a 1-hour TTL
    const ttl = 3600 + Math.floor(Math.random() * 360);
    await client.setEx(key, ttl, JSON.stringify(data));
  } catch (err) {
    console.error('Redis write failed', err);
  }

  return data;
}
